#include <stdio.h>
enum Status { STATUS_NEW, STATUS_ACTIVE, STATUS_CLOSED };
int main(void) {
 enum Status state = STATUS_ACTIVE;
 if (state == STATUS_ACTIVE) puts("Active");
 return 0;
}

#include <stdio.h>
enum Mode { MODE_READ = 1, MODE_WRITE = 2, MODE_APPEND = 4 };
int main(void) { enum Mode mode = MODE_APPEND; switch (mode) { case MODE_READ: puts("read"); break; case MODE_WRITE: puts("write"); break; case MODE_APPEND: puts("append"); break; default: puts("invalid"); } return 0; }
